stage_a_raw:
{
  "decisions": [
    {
      "decision": "capacity_constraint_aggregation",
      "evidence": "\"For each machine and time period, the production quantity multiplied by -71.79935969683524 for Machine 0 or -73.09691843304661 for Machine 1, plus the startup time multiplied by 6.342821301312698 for Machine 0 or 6.171760083826499 for Machine 1, plus the amount produced must be less than or equal to zero.\"",
      "options": [
        "per product-machine-period: -rate*x[p,m,t] + starttime*s[m,t] + x[p,m,t] <= 0",
        "per machine-period aggregated: -rate*sum_p x[p,m,t] + starttime*s[m,t] + sum_p x[p,m,t] <= 0"
      ],
      "plausibility": [
        0.5,
        0.5
      ],
      "majority_option": "per product-machine-period: -rate*x[p,m,t] + starttime*s[m,t] + x[p,m,t] <= 0"
    },
    {
      "decision": "production_linking_constraint",
      "evidence": "\"For each product, machine, and time period, decide whether to produce the product and how much to produce.\"",
      "options": [
        "include x[p,m,t] <= bigM * y[p,m,t]",
        "omit production linking (rely only on capacity and one-product constraints)"
      ],
      "plausibility": [
        0.6,
        0.4
      ],
      "majority_option": "omit production linking (rely only on capacity and one-product constraints)"
    },
    {
      "decision": "startup_linking_direction",
      "evidence": "\"If a machine is producing a product in a period but was not producing it in the previous period, a startup decision must be made.\"",
      "options": [
        "s[m,t] >= y[p,m,t] - y[p,m,t-1]",
        "y[p,m,t] - y[p,m,t-1] <= s[m,t] (equivalent form)"
      ],
      "plausibility": [
        0.5,
        0.5
      ],
      "majority_option": "s[m,t] >= y[p,m,t] - y[p,m,t-1]"
    },
    {
      "decision": "demand_satisfaction_formulation",
      "evidence": "\"the total production across machines, plus any inventory carried over from the previous period, minus any backlog from the previous period, must equal the demand for that period plus the current inventory minus the current backlog\"",
      "options": [
        "equality inventory balance only (no separate demand constraint)",
        "equality inventory balance plus explicit demand satisfaction constraint"
      ],
      "plausibility": [
        0.7,
        0.3
      ],
      "majority_option": "equality inventory balance only (no separate demand constraint)"
    },
    {
      "decision": "bigM_value",
      "evidence": "none",
      "options": [
        "bigM = 1.0",
        "bigM = 1000.0",
        "bigM = total demand or other large bound"
      ],
      "plausibility": [
        0.4,
        0.3,
        0.3
      ],
      "majority_option": "bigM = 1.0"
    },
    {
      "decision": "production_variable_domain",
      "evidence": "\"Production quantities, inventory levels, and backlogs must be non-negative.\"",
      "options": [
        "NonNegativeReals",
        "NonNegativeIntegers"
      ],
      "plausibility": [
        0.9,
        0.1
      ],
      "majority_option": "NonNegativeReals"
    }
  ]
}
